import test from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, readFile, rm, stat } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative, isAbsolute } from "node:path";

import { displayPath, extensionOf, requireExtension, textLimit } from "../index.js";
import { readOffice, writeDocx, writeXlsx } from "../index.js";

/** A context with exactly the fs surface the Office tools use. */
function fakeContext(root, mode = "workspace-write") {
	const resolve = (path, options = {}) => {
		const absolute = isAbsolute(path) ? path : join(options.cwd ?? root, path);
		return { targetKey: absolute, displayPath: absolute };
	};
	return {
		workingDirectory: { ensure: async () => root },
		fs: {
			sandboxMode: mode,
			resolve: async (path, options) => resolve(path, options),
			contains: (parent, child) => {
				const rel = relative(parent.targetKey, child.targetKey);
				return rel === "" || (!rel.startsWith("..") && !isAbsolute(rel));
			},
			stat: async (target) => {
				try {
					const info = await stat(target.targetKey);
					return { type: info.isFile() ? "file" : info.isDirectory() ? "directory" : "other", size: info.size };
				} catch {
					return undefined;
				}
			},
			readBytes: async (target) => new Uint8Array(await readFile(target.targetKey)),
			processPath: (target) => target.targetKey
		}
	};
}

const exec = { agent: {}, signal: undefined };

async function withWorkspace(fn) {
	const root = await mkdtemp(join(tmpdir(), "office-test-"));
	try {
		return await fn(root, fakeContext(root));
	} finally {
		await rm(root, { recursive: true, force: true });
	}
}

test("maps extensions and appends a missing one", () => {
	assert.equal(extensionOf("reports/a.DOCX"), "docx");
	assert.equal(requireExtension("reports/a", "docx", "doc"), "reports/a.docx");
	assert.equal(requireExtension("reports/a.docx", "docx", "doc"), "reports/a.docx");
	assert.throws(() => requireExtension("reports/a.doc", "docx", "doc"), (error) => error.code === "OFFICE_UNSUPPORTED");
	assert.throws(() => requireExtension("reports/a.pdf", "docx", "doc"), (error) => error.code === "OFFICE_BAD_ARGS");
});

test("clamps max_chars", () => {
	assert.equal(textLimit(undefined, 30000, 100000), 30000);
	assert.equal(textLimit(10, 30000, 100000), 1000);
	assert.equal(textLimit(999999, 30000, 100000), 100000);
	assert.equal(textLimit(Number.NaN, 30000, 100000), 30000);
});

test("writes and reads a docx inside the workspace", () => withWorkspace(async (root, ctx) => {
	const written = await writeDocx(ctx, exec, {
		path: "reports/weekly",
		markdown: "# 周报\n\n完成 **Office** 第一版。\n\n| 模块 | 状态 |\n| --- | --- |\n| docx | 完成 |\n"
	});
	assert.equal(written.path, "reports/weekly.docx");
	assert.ok(written.bytes > 100);
	assert.ok((await stat(join(root, "reports/weekly.docx"))).size > 100);

	const read = await readOffice(ctx, exec, { path: "reports/weekly.docx" }, { maxReadBytes: 1e7, maxTextChars: 30000, maxTextCharsLimit: 100000 });
	assert.equal(read.kind, "docx");
	assert.equal(read.truncated, false);
	assert.match(read.text, /# 周报/);
	assert.match(read.text, /\| 模块 \| 状态 \|/);
}));

test("writes and reads an xlsx with one sheet", () => withWorkspace(async (root, ctx) => {
	const written = await writeXlsx(ctx, exec, {
		path: "reports/costs.xlsx",
		csv: "名称,数量\n苹果,3\n香蕉,5\n=SUM(B2:B3)\n",
		sheet_name: "库存"
	});
	assert.equal(written.sheet, "库存");
	assert.equal(written.rows, 4);
	const read = await readOffice(ctx, exec, { path: "reports/costs.xlsx", sheet: "库存" }, { maxReadBytes: 1e7, maxTextChars: 30000, maxTextCharsLimit: 100000 });
	assert.equal(read.kind, "xlsx");
	assert.deepEqual(read.sheets, ["库存"]);
	assert.match(read.text, /苹果\t3/);
	assert.match(read.text, /=SUM\(B2:B3\)/);
}));

test("overwrites an existing document", () => withWorkspace(async (root, ctx) => {
	await writeDocx(ctx, exec, { path: "a.docx", markdown: "first" });
	await writeDocx(ctx, exec, { path: "a.docx", markdown: "second" });
	const read = await readOffice(ctx, exec, { path: "a.docx" }, { maxReadBytes: 1e7, maxTextChars: 30000, maxTextCharsLimit: 100000 });
	assert.match(read.text, /second/);
	assert.doesNotMatch(read.text, /first/);
}));

test("refuses paths outside the workspace", () => withWorkspace(async (root, ctx) => {
	await assert.rejects(
		writeDocx(ctx, exec, { path: "../escape.docx", markdown: "x" }),
		(error) => error.code === "OFFICE_SANDBOX_DENIED"
	);
	await assert.rejects(
		readOffice(ctx, exec, { path: "../escape.docx" }, { maxReadBytes: 1e7, maxTextChars: 30000, maxTextCharsLimit: 100000 }),
		(error) => error.code === "OFFICE_SANDBOX_DENIED"
	);
}));

test("refuses writes in read-only mode", () => withWorkspace(async (root, ctx) => {
	const readOnly = fakeContext(root, "read-only");
	await assert.rejects(
		writeDocx(readOnly, exec, { path: "a.docx", markdown: "x" }),
		(error) => error.code === "OFFICE_SANDBOX_DENIED"
	);
}));

test("reports a missing file clearly", () => withWorkspace(async (root, ctx) => {
	await assert.rejects(
		readOffice(ctx, exec, { path: "missing.docx" }, { maxReadBytes: 1e7, maxTextChars: 30000, maxTextCharsLimit: 100000 }),
		(error) => error.code === "OFFICE_NOT_FOUND"
	);
}));

test("rejects legacy and unsupported formats by name", () => withWorkspace(async (root, ctx) => {
	const caps = { maxReadBytes: 1e7, maxTextChars: 30000, maxTextCharsLimit: 100000 };
	await assert.rejects(readOffice(ctx, exec, { path: "a.doc" }, caps), (error) => /save (it|the document) as \.docx/.test(error.message));
	await assert.rejects(readOffice(ctx, exec, { path: "a.ppt" }, caps), (error) => /save the document as \.pptx/.test(error.message));
	await assert.rejects(readOffice(ctx, exec, { path: "a.pptx" }, caps), (error) => error.code === "OFFICE_UNSUPPORTED");
	await assert.rejects(readOffice(ctx, exec, { path: "a.pdf" }, caps), (error) => error.code === "OFFICE_UNSUPPORTED");
}));

test("returned paths are workspace-relative", () => {
	assert.equal(displayPath("/ws", "/ws/reports/a.docx"), "reports/a.docx");
	assert.equal(displayPath("/ws", "/other/a.docx"), "/other/a.docx");
});
